use rune::{col, el, row, text, El};
use rune::tok::type_;
use crate::{navigate, State};
use super::theme::*;
const PILL_CONTROL: f32 = 36.0;
fn pill(key: &'static str, icon: &rune::Pixels, enabled: bool, f: impl Fn(&mut State)+'static)->El { el().key(key).size(PILL_CONTROL,PILL_CONTROL).radius(18.0).fill(if enabled {rune::color::Color::TRANSPARENT} else {rune::color::Color{r:0.08,g:0.08,b:0.08,a:0.35}}).hover(HOVER).center().child(el().size(22.0,22.0).pixels(icon).opacity(if enabled{1.0}else{0.35})).on_press(f) }
pub fn zoom_menu() -> El { let p=[("300%",3.0),("200%",2.0),("100%",1.0),("66%",0.66),("50%",0.5)]; let mut m=col().key("zoom-presets").w(188.0).padding(6.0).gap(2.0).radius(12.0).fill(POPOVER).border(1.0,BORDER); for (l,v) in p {m=m.child(el().h(32.0).radius(6.0).hover(HOVER).center().child(text(l).font(type_::BODY).color(TEXT).center()).on_press(move|s:&mut State|{s.zoom=v;s.zoom_menu=false;}));} m.child(el().h(32.0).radius(6.0).hover(HOVER).center().child(text("Fit to Window").color(TEXT).center()).on_press(|s:&mut State|{s.zoom=1.0;s.pan_x=0.0;s.pan_y=0.0;s.zoom_menu=false;})) }
pub fn view(s: &State) -> El { let left=row().h(42.0).padding(3.0).gap(4.0).radius(21.0).fill(PILL).child(pill("previous",&s.icons.previous,s.current>0,|s|navigate(s,-1))).child(pill("next",&s.icons.next,s.current>=0&&(s.current as usize+1)<s.files.len(),|s|navigate(s,1))); let right=row().h(42.0).padding(3.0).gap(4.0).radius(21.0).fill(PILL).child(pill("zoom-in",&s.icons.zoom,true,|s|s.zoom=(s.zoom*1.25).min(8.0))).child(el().size(PILL_CONTROL,PILL_CONTROL).radius(18.0).hover(HOVER).center().child(el().size(20.0,20.0).pixels(&s.icons.down)).on_press(|s:&mut State|s.zoom_menu=!s.zoom_menu)); row().w_full().h_full().pin(Some(0.0),Some(0.0),Some(0.0),Some(0.0)).child(left.pin(Some(8.0),None,None,Some(8.0))).child(right.pin(None,None,Some(8.0),Some(8.0))) }
